import type {IShopConfig} from "../types";
import {ConsumableType} from "./types";
import type {ConsumableAmounts, IShopItemData} from "./types";

/** Возвращает пакет бонусов для id магазина без передачи ссылки на конфиг наружу. */
export function getShopItemData(shopConfig: IShopConfig, shopItemId: string): IShopItemData {
  const consumables = isShopItemId(shopConfig, shopItemId)
    ? shopConfig.shopItemConsumablesMap[shopItemId]
    : makeEmptyConsumables();

  return {
    consumables: {
      ...consumables,
    },
  };
}

/** Проверяет, что id есть в конфиге начисляемых пакетов бонусов. */
export function isShopItemId(shopConfig: IShopConfig, shopItemId: string): boolean {
  return shopItemId in shopConfig.shopItemConsumablesMap;
}

/** Создает пустой пакет для preview неизвестных id без общей ссылки на объект. */
function makeEmptyConsumables(): ConsumableAmounts {
  return {
    [ConsumableType.UNDO]: 0,
    [ConsumableType.HINT]: 0,
    [ConsumableType.MAGIC]: 0,
  };
}
