import {Align, AlignObject, makeAlign} from "@kvisaz/phaser-sugar";
import {
    asyncPreloadAssets,
    ButtonChild,
    CenteredContainerButton,
    ContainerButton,
    ExternalTopbarDialog,
    IUrlFrameData,
    preloadAssets,
} from "../../../common/game-core";
import {autoAssetsConfig} from "../../../autoAssetsConfig";
import {fitToSize} from "../../../common";
import {ConsumableType} from "../../../logic";
import {getLocalizedText} from "../../locale";
import {ConsumableButton} from "../../consumables";
import {
    Callback,
    ICoolTextButtonOptions,
    ImageAsset,
    INineSliceAsset,
    ITextBuildProps,
    ITextButtonOptions
} from "./types";
import {assetsChibiCoreFullAutoAssetsConst,} from '../../figmaAssets/assets-chibi-core-full-assets';

const coreSpiderAtlas = assetsChibiCoreFullAutoAssetsConst;
const fontAssets = autoAssetsConfig.fonts;

const coreSpiderAtlasAssetFixes = {
    buttonUndo: autoAssetsConfig.images.iconbuttonundo,
    iconPlay70x70: autoAssetsConfig.images.iconPlay70x70,
} as const;

interface ICardPlaceSize {
    width: number;
    height: number;
}

/**
 * Прелоад намеренно ограничен атласами, которые реально использует билдер.
 * Не возвращаем сюда полный autoAssetsConfig.preload.atlases, иначе снова подтянутся тестовые и старые пакеты.
 */
const viewElementBuilderPreloadAssets = {
    ...autoAssetsConfig.preload,
    fonts: [
        ...autoAssetsConfig.preload.fonts,
        /** подключаем синоним fontFamily для Russo One **/
        {
            name: "russoOneRegularAutoGeneratedAlias",
            url: autoAssetsConfig.fonts.russoOneRegular.url,
            fontFamily: "Russo One",
        },
    ]
} as const;

/**
 *  Делает визуальные элементы из конкретных ассетов
 *  Этот класс - точка привязки конкретной графики и ресурсов к игре
 *  Чтобы все изменения при смене названия у ресурсов приходилось делать только тут
 ***/
export class ViewElementBuilder {
    private align = new Align();

    constructor(private scene: Phaser.Scene) {
    }


    preload() {
        preloadAssets(this.scene, viewElementBuilderPreloadAssets);
    }


    async asyncPreload() {
        await asyncPreloadAssets(this.scene, viewElementBuilderPreloadAssets);
    }

    /**
     *  Game Component Elements - Card
     *  раньше тут был билдер карт теперь его заменил GamePlayCard
     ***/
    cardPlace(cardSize: ICardPlaceSize) {
        const imageAsset = autoAssetsConfig.images.cardplace279x405;
        const cardPlace = this.image(imageAsset);

        fitToSize({
            gameObject: cardPlace,
            width: cardSize.width,
            height: cardSize.height,
        });

        return cardPlace;
    }

    /** buttons **/
    buttonCloseCross(onClick: () => void) {
        const imageAsset = coreSpiderAtlas.iconCloseCrossWhite;
        return this.imageButton(imageAsset, onClick, {scale: 0.89});
    }

    buttonBack(onClick: () => void) {
        const imageAsset = autoAssetsConfig.images.iconBackGold;
        const button = this.imageButton(imageAsset, onClick);
        return button;
    }

    buttonSettings(onClick: () => void) {
        const imageAsset = autoAssetsConfig.images.gearGold;
        const button = this.imageButton(imageAsset, onClick);
        fitToSize({gameObject: button, width: 90, height: 90});
        return button;
    }

    buttonNewGame(onClick: () => void) {
        const imageAsset = coreSpiderAtlas.buttonNewgame;
        return this.imageButton(imageAsset, onClick, {scale: 0.89});
    }

    buttonReplayGame(onClick: () => void) {
        const imageAsset = coreSpiderAtlas.buttonReplay;
        return this.imageButton(imageAsset, onClick, {scale: 0.89});
    }

    buttonAutoComplete(onClick: () => void) {
        const imageAsset = coreSpiderAtlas.buttonReplay;
        return this.imageButton(imageAsset, onClick, {scale: 0.9});
    }

    buttonUndo(onClick: () => void) {
        const name = "consumableUndoButton";
        return this.consumableButton({
            buttonImageBuilder: () => this.createConsumableIcon(ConsumableType.UNDO),
            onClick,
            name,
        });
    }

    buttonShop(onClick: () => void) {
        const imageAsset = coreSpiderAtlas.iconShop;
        const button = this.imageButton(imageAsset, onClick);
        fitToSize({gameObject: button, width: 88, height: 88});
        return button;
    }

    buttonHint(onClick: () => void) {
        const name = "consumableHintButton";
        return this.consumableButton({
            buttonImageBuilder: () => this.createConsumableIcon(ConsumableType.HINT),
            onClick,
            name,
        });
    }

    buttonMagic(onClick: () => void) {
        const name = "consumableMagicButton";
        return this.consumableButton({
            buttonImageBuilder: () => this.createConsumableIcon(ConsumableType.MAGIC),
            onClick,
            name,
        });
    }

    buttonPrimary(text: string, onClick: () => void, options?: ITextButtonOptions) {
        const imageAsset = coreSpiderAtlas.uiButtonAccentNine20;
        return this.textButton(text, onClick, imageAsset, options);
    }

    buttonSecondary(text: string, onClick: () => void, options?: ITextButtonOptions) {
        const imageAsset = coreSpiderAtlas.uiButtonNormalNine20;
        return this.textButton(text, onClick, imageAsset, options);
    }

    buttonWarning(text: string, onClick: () => void, options?: ITextButtonOptions) {
        const imageAsset = coreSpiderAtlas.uiButtonWarningNine20;
        return this.textButton(text, onClick, imageAsset, options);
    }

    /** new spider buttons **/
    private spiderButton(label: string, onClick: Callback, options: ICoolTextButtonOptions = {}) {

        const imageAsset: ImageAsset = options.bgImageAsset ?? coreSpiderAtlas.uiButtonGreenHeight82Nine36;
        const fontSizePx = options.fontSizePx ?? 48;
        const fontCssColor = options.fontCssColor ?? '#FFFFFF';
        const width = options.width ?? 330;
        const height = options.height ?? 90;

        const bg = this.nineSlice({
            ...imageAsset,
            width,
            height,
        });

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.russoOneRegular.fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor
        };
        const textObject = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);


        return this.addButtonSound(
            new CenteredContainerButton({
                gameObjects: [bg, textObject],
                onClick,
                options: {
                    once: false,
                    onDisabled: () => {
                        bg.setTint(0xdedede);
                        textObject.setAlpha(0.65);
                    },
                    onEnabled: () => {
                        bg.clearTint();
                        textObject.setAlpha(1);
                    },
                },
            }),
        );
    }

    buttonGreen(label: string, onClick: Callback, options: ICoolTextButtonOptions = {}) {
        options.bgImageAsset = coreSpiderAtlas.uiButtonGreenHeight82Nine36;
        return this.spiderButton(label, onClick, options);
    }

    buttonRed(label: string, onClick: Callback, options: ICoolTextButtonOptions = {}) {
        options.bgImageAsset = coreSpiderAtlas.uiButtonRedHeight82Nine36;
        return this.spiderButton(label, onClick, options);
    }

    buttonYellow(label: string, onClick: Callback, options: ICoolTextButtonOptions = {}) {
        options.bgImageAsset = coreSpiderAtlas.uiButtonYellowHeight82Nine36;
        return this.spiderButton(label, onClick, options);
    }

    /**
     *  Start Screen Images
     ***/

    startHeroes() {
        const cards = this.image(coreSpiderAtlas.startHeroCardsTriple);
        const {black, red} = this.getCatHeroes()

        this.align.setPosition(cards, 218, 588);
        this.align.setPosition(black, 321, 439);
        this.align.setPosition(red, 1214, 440);
    }

    getCatHeroes() {
        const black = this.image(coreSpiderAtlas.startHeroBlackCat);
        const red = this.image(coreSpiderAtlas.startHeroRedCat);

        return {
            black, red
        }
    }


    /**
     *  Dialogs
     ***/
    getConsumableIconAsset(type: ConsumableType): ImageAsset {
        const assetMap: Record<ConsumableType, ImageAsset> = {
            [ConsumableType.UNDO]: coreSpiderAtlasAssetFixes.buttonUndo,
            [ConsumableType.HINT]: coreSpiderAtlas.buttonHint,
            [ConsumableType.MAGIC]: coreSpiderAtlas.buttonMagic,
        };
        return assetMap[type];
    }

    dialogTopBar(args: { title: string; width: number; onCloseClick: () => void }) {
        const topBarPadding = 16;

        const topBarContent = new Phaser.GameObjects.Container(this.scene, 0, 0);
        const title = this.textDialogTitle(args.title);
        const topBarBg = new Phaser.GameObjects.Zone(
            this.scene,
            0,
            0,
            args.width,
            title.getBounds().height + topBarPadding * 2,
        );
        const closeButton = this.buttonCloseCross(args.onCloseClick);
        const {align} = this;
        align.anchor(topBarBg).center(title);
        align.rightIn(closeButton).centerY(closeButton);
        topBarContent.add([topBarBg, title, closeButton]);

        return topBarContent;
    }

    dialogExternalTopTitle(args: {
        beforeOpen?: () => void;
        onClose?: () => void;
        onCloseClick?: () => void;
        content: Phaser.GameObjects.Container & AlignObject;
        title: string;
        width?: number;
        height?: number;
        isAutoOpen?: boolean;
        isCloseOnOverlayClick?: boolean;
    }) {
        const bgNineAsset = coreSpiderAtlas.uiDialogBgLightNine40;
        const padding = 40;
        const dialogAnimationDuration = 150;

        const bgBuilder = (width: number, height: number) =>
            this.nineSlice({
                ...bgNineAsset,
                width,
                height,
                padding,
            });

        const topBarContent = this.dialogTopBar({
            title: args.title,
            width: args.width ?? 1100,
            onCloseClick: closeClick,
        });

        const dialog = new ExternalTopbarDialog({
            topBarContent,
            beforeOpen: args.beforeOpen,
            onClose: args.onClose,
            content: args.content,
            bgBuilder,
            isAutoOpen: args.isAutoOpen,
            width: args.width,
            height: args.height,
            animationDuration: dialogAnimationDuration,
            isCloseOnOverlayClick: args.isCloseOnOverlayClick,
        });

        function closeClick() {
            dialog.close();
            args.onCloseClick?.();
        }

        return dialog;
    }

    /**
     * Spider Ui Design pack
     */
    dialogBgLightNine({width, height}: { width: number, height: number }): Phaser.GameObjects.NineSlice {
        const nineSliceAsset = coreSpiderAtlas.uiDialogBgLightNine40;
        return this.nineSlice({...nineSliceAsset, width, height, padding: 40});
    }

    getFontFamilyRusso() {
        return fontAssets.russoOneRegular.fontFamily;
    }

    getFontFamilyRegular() {
        return fontAssets.robotoRegular.fontFamily;
    }

    /**
     *  Sounds
     ***/

    /** hide concrete sounds, use sound fabric like addButtonSound **/
    public addButtonSound<T extends Phaser.GameObjects.GameObject>(button: T): T {
        button.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () =>
            this.scene.events.emit('onButtonClick', {gameObjectName: button.name})
        );
        button.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () =>
            this.scene.events.emit('onButtonHover', {gameObjectName: button.name})
        );
        return button;
    }

    /**
     *  Texts View Elements
     ***/
    textSmallStart(label: string) {
        const fontFamily = fontAssets.russoOneRegular.fontFamily;
        const fontSizePx = 24;
        const fontCssColor = '#FFFFFF';
        const strokeCssColor = 'rgba(0,0,0, 65)';
        const strokeThickness = 6;

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor,
            strokeThickness,
            stroke: strokeCssColor,
        };
        const textObj = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
        this.scene.add.existing(textObj);
        return textObj;
    }


    textMain(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        const defaultFontSize = "32px";

        function selectFamily(options: ITextBuildProps) {
            if (options.weight === "bold") return autoAssetsConfig.fonts.robotoBold.fontFamily;
            if (options.weight === "semibold") return autoAssetsConfig.fonts.robotoSemibold.fontFamily;
            return autoAssetsConfig.fonts.robotoRegular.fontFamily;
        }

        const fontSize = options.fontSize ?? defaultFontSize;

        const style: Phaser.Types.GameObjects.Text.TextStyle = {
            ...options,
            fontFamily: selectFamily(options),
            fontSize,
        };

        return this.scene.add.existing(new Phaser.GameObjects.Text(this.scene, 0, 0, text, style));
    }

    textStartScreenTitle(): Phaser.GameObjects.Text {
        const label = getLocalizedText("start.logo.title");
        const fontSizePx = 100;
        const fontCssColor = '#FF9735';
        const strokeCssColor = '#FFFFFF';

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.rubikBubblesRegular.fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor,
            strokeThickness: 14,
            stroke: strokeCssColor,
        };
        const textObj = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
        this.scene.add.existing(textObj);
        return textObj;
    }

    textStartScreenSubTitle(): Phaser.GameObjects.Text {
        const label = getLocalizedText("start.logo.subtitle");
        const fontSizePx = 80;
        const fontCssColor = '#ea9443';
        const strokeCssColor = '#FFFFFF';

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.rubikBubblesRegular.fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor,
            strokeThickness: 14,
            stroke: strokeCssColor,
        };
        const textObj = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
        this.scene.add.existing(textObj);
        return textObj;
    }

    textDialogTitle(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        return this.textMain(text, {
            weight: "semibold",
            color: "#ffffff",
            align: "center",
            fontSize: "64px",
            ...options,
        });
    }

    textButtonBasic(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        return this.textMain(text, {
            weight: "semibold",
            color: "#ffffff",
            align: "center",
            fontSize: "48px",
            ...options,
        });
    }

    textDialog(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        return this.textMain(text, {
            weight: "regular",
            color: "#485743",
            align: "center",
            fontSize: "48px",
            ...options,
        });
    }

    textResourceCounter(text: string): Phaser.GameObjects.Text {
        return this.textMain(text, {
            weight: "bold",
            color: "#ffffff",
            align: "center",
            fontSize: "30px",
        });
    }

    deckCountInfo(text: string): Phaser.GameObjects.Text {
        return this.textMain(text, {
            weight: "semibold",
            color: "#ffffff",
            align: "center",
            fontSize: "22px",
        }).setAlpha(0.6)
    }

    shopItemRewardButton(onClick: () => void) {
        const bg = this.nineSlice({
            ...coreSpiderAtlas.uiButtonGreenHeight82Nine36,
            width: 292,
            height: 73,
            padding: 36
        });

        const labelText = getLocalizedText('shop.free');
        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.russoOneRegular.fontFamily,
            fontSize: `${32}px`,
            color: '#ffffff'
        };
        const label = new Phaser.GameObjects.Text(this.scene, 0, 0, labelText, textStyle);

        const playIcon = this.image(coreSpiderAtlasAssetFixes.iconPlay70x70);

        makeAlign(align => {
            align.anchor(bg);
            align.center(label, -35, 0);
            align.rightIn(playIcon, -3);
        })

        return this.containerButton([
            bg, label, playIcon
        ], onClick);
    }

    shopItemBuyButton(labelText: string, onClick: () => void) {
        const bg = this.nineSlice({
            ...coreSpiderAtlas.uiButtonYellowHeight82Nine36,
            width: 292,
            height: 73,
            padding: 36
        });

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.russoOneRegular.fontFamily,
            fontSize: `${32}px`,
            color: '#ffffff'
        };
        const label = new Phaser.GameObjects.Text(this.scene, 0, 0, labelText, textStyle);


        makeAlign(align => {
            align.anchor(bg);
            align.center(label);
        })

        return this.containerButton([
            bg, label
        ], onClick);
    }

    /** Private helpers **/
    private createRewardPlayIcon(): Phaser.GameObjects.Image {
        return this.image(coreSpiderAtlasAssetFixes.iconPlay70x70);
    }

    private createConsumableIcon(type: ConsumableType): Phaser.GameObjects.Image {
        return this.image(this.getConsumableIconAsset(type));
    }

    private consumableButton({
                                 name,
                                 onClick,
                                 buttonImageBuilder,
                             }: {
        buttonImageBuilder: () => ButtonChild;
        onClick: () => void;
        name: string;
    }) {
        const nineSliceAsset = coreSpiderAtlas.uiUsefulBgNine32;

        return this.addButtonSound(
            new ConsumableButton({
                name,
                scene: this.scene,
                onClick: () => {
                    onClick();
                },
                initAmount: 0,
                buttonImageBuilder,
                rewardIconBuilder: () => this.createRewardPlayIcon(),
                textBgBuilder: (width, height) =>
                    this.nineSlice({...nineSliceAsset, width, height, padding: 32}),
                textBuilder: (text) => this.textResourceCounter(text),
            }),
        );
    }

    private imageButton(
        imageAsset: ImageAsset,
        onClick: () => void,
        options: { once?: boolean; scale?: number } = {},
    ) {
        const {once = false, scale = 1} = options;
        const image = this.image(imageAsset);

        const button = this.addButtonSound(
            new CenteredContainerButton({
                gameObjects: [image],
                onClick,
                options: {
                    once,
                    onDisabled: () => image.setTint(0xdedede),
                    onEnabled: () => image.clearTint(),
                    disableAfterClick: {
                        ms: 100,
                    },
                },
            }),
        );

        button.setScale(scale);

        return button;
    }

    private containerButton(
        children: ButtonChild[],
        onClick: () => void,
        options: { once?: boolean; scale?: number } = {},
    ) {
        const {once = false, scale = 1} = options;

        const button = this.addButtonSound(
            new ContainerButton({
                gameObjects: [...children],
                onClick,
                options: {
                    once,
                    disableAfterClick: {
                        ms: 100,
                    },
                },
            }),
        );

        button.setScale(scale);

        return button;
    }

    private textButton(
        text: string,
        onClick: () => void,
        imageAsset: ImageAsset,
        options?: ITextButtonOptions,
    ) {
        let textOptions: ITextBuildProps | undefined;
        if (options?.width) {
            const textWidth = options.width * 0.8;
            textOptions = {
                fixedWidth: textWidth,
                wordWrap: {
                    width: textWidth,
                },
            };
        }

        if (options?.fontSizePx) {
            textOptions = {
                ...textOptions,
                fontSize: `${options.fontSizePx}px`,
            };
        }

        const textLabel = this.textButtonBasic(text, textOptions);
        const textBounds = textLabel.getBounds();

        const minWidth = 220;
        const paddingX = options?.paddingX ?? 32;
        const paddingY = options?.paddingY ?? 0;
        const width = options?.width ?? Math.max(minWidth, textBounds.width + 2 * paddingX);
        const height = options?.height ?? 80 + 2 * paddingY;
        const bg = this.nineSlice({...imageAsset, width, height, padding: 32});

        return this.addButtonSound(
            new CenteredContainerButton({
                gameObjects: [bg, textLabel],
                onClick,
                options: {
                    disableAfterClick: {
                        ms: options?.disableAfterClickMs ?? 0,
                    },
                    once: false,
                    onDisabled: (button) => button.setAlpha(0.8),
                    onEnabled: (button) => button.setAlpha(1),
                },
            }),
        );
    }

    image({url, frameName}: IUrlFrameData) {
        return this.scene.add.existing(new Phaser.GameObjects.Image(this.scene, 0, 0, url, frameName));
    }

    private nineSlice({url, frameName, width, height, padding = 20}: INineSliceAsset) {
        return this.scene.add.existing(
            new Phaser.GameObjects.NineSlice(
                this.scene,
                0,
                0,
                url,
                frameName,
                width,
                height,
                padding,
                padding,
                padding,
                padding,
            ),
        );
    }

}
