import packageInfo from "../package.json";
import {phaserGameConfig} from "./config";
import {gameScenes} from "./scenes";
import {getLocalizedText} from "./assets";
import {HtmlRoot} from "./common/html";
import {GameServiceProvider} from "./services";
import {buildConstants} from './constants.build';
import {iosResumePatch} from './common/sound/IosResumePatch/iosResumePatch';

const versionLabel = buildConstants.publishBuild ? 'prod' : 'test';
console.log(`${packageInfo.description} ${versionLabel} v.${packageInfo.version} starting...`);

HtmlRoot.root = document.getElementById("game")!;

GameServiceProvider.reset();

const phaserGame = new Phaser.Game({
    ...phaserGameConfig,
    scene: [...gameScenes],
});

/* ---------------------------------------------------------
 *  восстановление контекста звука на iOS - общая проблема
 * --------------------------------------------------------- */
iosResumePatch(phaserGame);

/* ---------------------------------------------------------
 *  Отключаем контекстное меню браузера - требования Y
 * --------------------------------------------------------- */
document.body.addEventListener("contextmenu", (e) => e.preventDefault());

/* ---------------------------------------------------------
 *  Включаем локализованный title
 * --------------------------------------------------------- */
const titleText = getLocalizedText("start.logo.title");
const subTitleText = getLocalizedText("start.logo.subtitle");
document.title = `${titleText} - ${subTitleText}`;
