/**
 * Собираем тут соотношения ассетов и звуков в игре!
 **/
import {GameEventName, IGameEvents, PlayerMoveReactionType} from './scenes/events';


interface IPhaserSoundConfig {
    soundName: string;
    volume?: number;
}


type SoundEventCallback<EventName extends GameEventName> = (
    scene: Phaser.Scene,
    eventData: IGameEvents[EventName],
) => void;

export type SoundForEvents = Partial<{
    [EventName in GameEventName]: SoundEventCallback<EventName>;
}>;

/** Реакции на события в игре - звуки подключаем тут, декларативно и четко **/
const soundForEvents: SoundForEvents = {
    playerCardsMoveStart: (scene, eventData) => {

        const playerMoveReactionSoundMap: Record<PlayerMoveReactionType, IPhaserSoundConfig | undefined> = {
            transfer: {soundName: 'cardFlip'},
            stockDeal: undefined,
            wrongCard: {soundName: 'cardSfx03', volume: 0.5},
            wrongDrop: {soundName: 'cardSfx03', volume: 0.5},
            wrongStockDeal: {soundName: 'cardSfx03', volume: 0.5},
            undo: {soundName: 'cardFlip'},
            collect: {soundName: 'cardFlip'},
            magic: {soundName: 'cardFlip'},
        };

        const gameSoundConfig = playerMoveReactionSoundMap[eventData.type];
        if (gameSoundConfig == null) return;

        const {soundName, volume} = gameSoundConfig;
        scene.sound.play(soundName, {volume});
    },

    spiderGameWin: (scene) => {
        scene.sound.play('fanfare', {volume: 0.5});
    },

    spiderStockDealCardPlace: (scene) => {
        scene.sound.play('cardFlip', {volume: 1});
    },

    paidPurchaseSuccess: (scene) => {
        scene.sound.play('purchaseSuccess', {volume: 0.75});
    },

    onButtonClick: (scene) => scene.sound.play("click"),
    onButtonHover: (scene) => scene.sound.play("cardFlip")
};


export const musicConfig = {
    soundName: 'music', volume: 0.09
}


/**
 * редкий кейс
 *  - оверлей сцена которая живет постоянно для диалогов
 * лучше избегать ее конечно!
 * **/
const attachedScenes = new WeakSet<Phaser.Scene>();

type SoundEventHandler = (scene: Phaser.Scene, eventData?: unknown) => void;

export function attachSoundForEvents(scene: Phaser.Scene): void {
    if (attachedScenes.has(scene)) return;
    attachedScenes.add(scene);

    Object.entries(soundForEvents).forEach(([eventName, callback]) => {
        if (!callback) return;

        const handler = callback as SoundEventHandler;

        scene.events.on(eventName, (eventData?: unknown) => {
            handler(scene, eventData);
        });
    });
}
