import {makeAlign} from "@kvisaz/phaser-sugar";
import {LayoutUtils, SceneEvents} from "../../common";
import type {ThemeCardBack} from "../../config.themes";
import {GameServiceProvider} from "../../services";
import {assetsViewsAutoAssets} from "../auto_generated/assets-views-assets";
import {ButtonEvents} from "../auto_generated/utils/addButtonViewInteractivity";
import {makeContainerInteractive, setLeftTop} from "../auto_generated/utils/utils";
import {ShopSelectLabel} from "./shop-select-label";

const CARD_BACKS_IN_ROW = 6;
const CARD_BACK_GAP = 20;
const CARD_BACK_WIDTH = 180;
const CARD_BACK_HEIGHT = 261;
const CARD_BACK_ROW_STEP = CARD_BACK_HEIGHT + CARD_BACK_GAP;
const CARD_BACK_COL_STEP = CARD_BACK_WIDTH + CARD_BACK_GAP;
const CARD_BACK_SELECTED_CHECK_LEFT = 70;
const CARD_BACK_SELECTED_CHECK_TOP = 161;

export interface ICreateCardBackShopContentProps {
    scene: Phaser.Scene;
    cardBacks: ThemeCardBack[];
}

interface ICreateCardBackShopContentEvents {
    setCardBack: { id: string; cardBackAssetName: string };
}

interface ICreateCardBackThumbProps {
    scene: Phaser.Scene;
    cardBack: ThemeCardBack;
    isSelected: boolean;
    onSelect: (thumb: CardBackThumb) => void;
}

export function createCardBackShopContent(props: ICreateCardBackShopContentProps): Phaser.GameObjects.Container {
    const {scene, cardBacks} = props;
    const playerData = GameServiceProvider.get().playerData.get();
    const selectedCardBackAssetName = playerData.cardBackAssetName ?? cardBacks[0]?.image.name;
    const content = new Phaser.GameObjects.Container(scene, 0, 0);
    const thumbs: CardBackThumb[] = [];

    cardBacks.forEach((cardBack) => {
        thumbs.push(
            new CardBackThumb({
                scene,
                cardBack,
                isSelected: cardBack.image.name === selectedCardBackAssetName,
                onSelect: (selectedThumb) => {
                    thumbs.forEach((thumb) => thumb.setSelected(thumb === selectedThumb));
                },
            }),
        );
    });

    content.add(thumbs);
    LayoutUtils.makeGridByRow(thumbs, CARD_BACKS_IN_ROW, CARD_BACK_COL_STEP, CARD_BACK_ROW_STEP);

    return content;
}

export class CardBackThumb extends Phaser.GameObjects.Container {
    private readonly sceneEvents: SceneEvents<ICreateCardBackShopContentEvents>;
    private readonly selectedFrame: Phaser.GameObjects.Image;
    private readonly selectedCheck: Phaser.GameObjects.Image;
    private readonly selectLabel?: ShopSelectLabel;
    private isSelected = false;

    constructor(private readonly props: ICreateCardBackThumbProps) {
        super(props.scene, 0, 0);

        this.name = props.cardBack.id;
        this.sceneEvents = new SceneEvents<ICreateCardBackShopContentEvents>({scene: props.scene, autoUnSub: this});

        const thumb = createCardBackThumb({scene: props.scene, cardBack: props.cardBack});
        this.add(thumb);

        const selectLabel = new ShopSelectLabel({scene: props.scene});
        makeAlign((align) => align.anchor(thumb).bottomIn(selectLabel, -5).rightIn(selectLabel, -5));
        this.add(selectLabel);
        this.selectLabel = selectLabel;

        this.selectedFrame = createSelectedFrame(props.scene);
        this.selectedCheck = createSelectedCheck(props.scene);
        this.add([this.selectedFrame, this.selectedCheck]);
        this.setSelected(props.isSelected);

        makeContainerInteractive(this);
        this.on(Phaser.Input.Events.POINTER_OVER, () => {
            if (this.isSelected) {
                return;
            }

            this.scene.events.emit(ButtonEvents.onHover, {gameObjectName: this.name});
        });
        this.on(Phaser.Input.Events.POINTER_DOWN, () => {
            if (this.isSelected) {
                return;
            }

            this.scene.events.emit(ButtonEvents.onClick, {gameObjectName: this.name});
            this.sceneEvents.emit("setCardBack", {
                id: this.props.cardBack.id,
                cardBackAssetName: this.props.cardBack.image.name,
            });
            this.props.onSelect(this);
        });
    }

    setSelected(isSelected: boolean): void {
        this.isSelected = isSelected;
        this.selectedFrame.setVisible(isSelected);
        this.selectedCheck.setVisible(isSelected);
        this.selectLabel?.setVisible(!isSelected);
    }
}

function createCardBackThumb(
    props: Pick<ICreateCardBackThumbProps, "scene" | "cardBack">,
): Phaser.GameObjects.Image {
    const {scene, cardBack} = props;
    const thumb = new Phaser.GameObjects.Image(scene, 0, 0, cardBack.image.url, cardBack.image.frameName);

    thumb.name = cardBack.id;
    thumb.setDisplaySize(CARD_BACK_WIDTH, CARD_BACK_HEIGHT);
    setLeftTop(thumb, 0, 0);

    return thumb;
}

function createSelectedFrame(scene: Phaser.Scene): Phaser.GameObjects.Image {
    const frame = new Phaser.GameObjects.Image(
        scene,
        0,
        0,
        assetsViewsAutoAssets.cardSelected279x405.url,
        assetsViewsAutoAssets.cardSelected279x405.frameName,
    );

    frame.name = assetsViewsAutoAssets.cardSelected279x405.name;
    frame.setDisplaySize(CARD_BACK_WIDTH, CARD_BACK_HEIGHT);
    setLeftTop(frame, 0, 0);

    return frame;
}

function createSelectedCheck(scene: Phaser.Scene): Phaser.GameObjects.Image {
    const check = new Phaser.GameObjects.Image(
        scene,
        0,
        0,
        assetsViewsAutoAssets.iconCheckmark100.url,
        assetsViewsAutoAssets.iconCheckmark100.frameName,
    );

    check.name = assetsViewsAutoAssets.iconCheckmark100.name;
    setLeftTop(check, CARD_BACK_SELECTED_CHECK_LEFT, CARD_BACK_SELECTED_CHECK_TOP);

    return check;
}
