import { defaultSpiderConfig, SceneEvents, State } from "../../../common";
import type { ISpiderConfig } from "../../../common";
import { freeConsumablesConfig } from "../../../config.consumables";
import { ISpiderGameSceneViewLogicEvents } from "./events";
import { SpiderDealSession } from "./SpiderDealSession";
import type { ISpiderGameSceneViewState } from "./types";
import { GameServiceProvider } from "../../../services";

interface IProps {
  /**
   * важный момент - стараемся минимизировать использование сцены
   * допускаются
   * - работа с событиями
   * - работа с таймерами
   * запрещено обращение к свойствам сцены ради обращения к игровым объектам
   * **/
  scene: Phaser.Scene;
  spiderConfig?: ISpiderConfig;
}

interface IStartNewGameProps {
  shuffleDeck: boolean;
  grantEntryConsumables?: boolean;
}

const defaultState: ISpiderGameSceneViewState = {
  step: "idle",
  historyLength: 0,
  dealCount: 0,
  undoCount: 0,
  dealsLeft: 0,
  isDealPossible: false,
  isUndoPossible: false,
  completedSequences: 0,
  totalSequences: 0,
  progress: 0,
  isCollectPossible: false,
  isHintPossible: false,
  isMagicPossible: false,
  stockCount: 0,
  tableauCounts: [],
  isWin: false,
};

export class SpiderGameSceneViewLogic {
  private readonly state: State<ISpiderGameSceneViewState>;
  private readonly sceneEvents: SceneEvents<ISpiderGameSceneViewLogicEvents>;
  private readonly unSubs: Array<() => void> = [];

  private readonly spiderConfig: ISpiderConfig;
  private readonly dealSession: SpiderDealSession;

  constructor(private readonly props: IProps) {
    this.spiderConfig = props.spiderConfig ?? defaultSpiderConfig;
    this.dealSession = new SpiderDealSession({ spiderConfig: this.spiderConfig });

    this.state = new State<ISpiderGameSceneViewState>({ ...defaultState });
    this.unSubs.push(() => this.state.unSubScribeAll());

    this.sceneEvents = new SceneEvents<ISpiderGameSceneViewLogicEvents>({ scene: props.scene });
    this.unSubs.push(() => this.sceneEvents.unSubscribeAll());

    this.subscribeToUiEvents();
    this.subscribeToSpiderEvents();
  }

  destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  observable() {
    return this.state;
  }

  /** Запускает новую или повторную раздачу Spider и опционально выдает входной бонус. */
  startNewGame({ shuffleDeck, grantEntryConsumables }: IStartNewGameProps) {
    this.state.setState({ ...defaultState });
    if (grantEntryConsumables === true) {
      this.sceneEvents.emit("grantConsumables", {
        consumables: freeConsumablesConfig.gameSceneEntry,
      });
    }

    const cards = shuffleDeck ? this.dealSession.nextDeal() : this.dealSession.replayDeal();
    this.sceneEvents.emit("spiderStart", { cards, config: this.spiderConfig });
  }

  private subscribeToUiEvents() {
    const { sceneEvents } = this;

    sceneEvents.on("uiNewGameClick", () => {
      this.startNewGame({ shuffleDeck: true, grantEntryConsumables: false });
    });

    sceneEvents.on("uiReplayClick", () => {
      this.startNewGame({ shuffleDeck: false, grantEntryConsumables: false });
    });
  }

  private subscribeToSpiderEvents() {
    const { sceneEvents } = this;

    sceneEvents.on("spiderStateUpdate", (state) => {
      const currentState = this.state.getState();
      const hasInitialDeal = state.tableauCounts.some((count) => count.closed + count.open > 0);

      this.state.setState({
        ...state,
        dealCount: hasInitialDeal ? Math.max(currentState.dealCount, 1) : currentState.dealCount,
        undoCount: currentState.undoCount,
      });
    });

    sceneEvents.on("playerCardsMoveStart", (move) => {
      if (move.type === "stockDeal") {
        this.state.setState((state) => ({
          ...state,
          dealCount: state.dealCount + 1,
        }));
      }

      if (move.type === "undo") {
        this.state.setState((state) => ({
          ...state,
          undoCount: state.undoCount + 1,
        }));
      }
    });

    sceneEvents.on("spiderStockDealComplete", () => {
      const state = this.state.getState();
      if (!GameServiceProvider.get().isFullAdEnabled || state.step !== "idle" || state.isWin) {
        return;
      }

      sceneEvents.emit("requestCommonAd");
    });

    sceneEvents.on("spiderGameWin", () => {
      this.requestGameOverDialog();
    });
  }

  /** Запрашивает GameOver-диалог после production-события победы SpiderView. */
  private requestGameOverDialog(): void {
    GameServiceProvider.get().signalGameplayStop();
    this.sceneEvents.emit("onGameOverDialogRequest");
  }
}
