import {Align, AlignMethod, AlignObject, layoutChain, makeAlign} from "@kvisaz/phaser-sugar";
import {viewGoldShopData} from "../auto_generated/assets-views.view";
import {createButtonBack} from "./button-back";
import {BonusShopItem} from "./BonusShopItem";
import {BonusShopItemData} from "./types";
import {getLocalizedText} from '../../assets';
import {onSceneLocaleChange} from '../../common';

interface IBonusShopProps {
    scene: Phaser.Scene;
    reward?: BonusShopItemData;
    shopItems?: BonusShopItemData[];
}

const VIEW_PADDING = 30;
const VIEW_PADDING_TOP = VIEW_PADDING;
const VIEW_PADDING_BOTTOM = 5;
const ITEM_GAP = 20;
const ITEM_TOP_IN = 100;

/** Витрина магазина пакетов бонусов на базе generated viewGoldShopData. */
export class BonusShop extends Phaser.GameObjects.Container {
    private readonly items: BonusShopItem[];
    private readonly bg: Phaser.GameObjects.NineSlice;
    private readonly title: Phaser.GameObjects.Text;
    private readonly backButton: Phaser.GameObjects.Container;

    /** Создает адаптивную витрину из reward-итема и трех buy-итемов. */
    constructor(private readonly props: IBonusShopProps) {
        super(props.scene, 0, 0);

        this.name = viewGoldShopData.name;
        this.setSize(viewGoldShopData.width, viewGoldShopData.height);
        this.items = this.createItems();
        this.bg = this.createBg();
        this.title = this.createTitle();
        this.backButton = this.createBackButton();

        this.layoutContent();
        this.add([this.bg, this.title, this.backButton, ...this.items]);
    }

    /** Создает элементы магазина в порядке config: reward, затем три покупки. */
    private createItems(): BonusShopItem[] {
        const items: BonusShopItem[] = [];
        const {scene, reward, shopItems = []} = this.props;

        if (reward != null) {
            items.push(new BonusShopItem({
                scene,
                itemType: "reward",
                item: reward,
            }));
        }

        shopItems.forEach((item) => {
            items.push(new BonusShopItem({
                scene,
                itemType: "buy",
                item,
            }));
        });

        return items;
    }

    /** Создает адаптивный фон диалога из generated nine-slice. */
    private createBg(): Phaser.GameObjects.NineSlice {
        const data = viewGoldShopData.children["ui.dialog.bg.light.nine.40"];
        const itemRow = this.createItemRow();
        const bounds = itemRow.getBounds();
        const width = bounds.width + VIEW_PADDING * 2;
        const height = bounds.height + VIEW_PADDING_TOP + VIEW_PADDING_BOTTOM + ITEM_TOP_IN;
        const padding = data.asset.ninePadding ?? 40;

        const bg = new Phaser.GameObjects.NineSlice(
            this.scene,
            0,
            0,
            data.asset.url,
            data.asset.frameName,
            width,
            height,
            padding,
            padding,
            padding,
            padding,
        );
        bg.name = data.asset.name;

        Align.setLeftTop(
            bg,
            data.x - viewGoldShopData.width / 2,
            data.y - viewGoldShopData.height / 2,
        );

        return bg;
    }

    /** Создает заголовок магазина из generated text data. */
    private createTitle(): Phaser.GameObjects.Text {
        const data = viewGoldShopData.children.textGoldShopTitle;
        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            ...data.text.style,
            fontSize: 38
        };
        const getTitleText = () => getLocalizedText('shop.title');
        const title = new Phaser.GameObjects.Text(
            this.scene,
            0,
            0,
            getTitleText(),
            textStyle,
        );
        title.name = data.text.name || "";
        title.setOrigin(0, 0);

        Align.setLeftTop(
            title,
            data.x - viewGoldShopData.width / 2,
            data.y - viewGoldShopData.height / 2,
        );

        const unsubscribeLocale = onSceneLocaleChange(this.scene, () => {
            title.setText(getTitleText());
        });
        title.once(Phaser.GameObjects.Events.DESTROY, unsubscribeLocale);

        return title;
    }

    /** Создает кнопку закрытия из существующего tuned-компонента back. */
    private createBackButton(): Phaser.GameObjects.Container {
        const data = viewGoldShopData.children.buttonBack;
        const button = createButtonBack(this.scene);

        Align.setLeftTop(
            button,
            data.x - viewGoldShopData.width / 2,
            data.y - viewGoldShopData.height / 2,
        );

        return button;
    }

    /** Выполняет адаптивную раскладку: фон оборачивает ряд товаров, title/back привязаны к фону. */
    private layoutContent(): void {
        const itemRow = this.createItemRow();

        makeAlign((align) => {
            align.anchor(this.bg).centerX(this.title).topIn(this.title, 25);
            align.anchor(this.bg).rightIn(this.backButton, -20).topIn(this.backButton, 10);
            align.anchor(this.bg).centerX(itemRow).topIn(itemRow, ITEM_TOP_IN);
        });
    }

    /** Возвращает layout-объект ряда товаров без создания новых display objects. */
    private createItemRow(): AlignObject {
        return layoutChain({
            children: this.items,
            alignToNext: AlignMethod.RIGHT_TO,
            nextOffsetX: ITEM_GAP,
            alignToAnchor: AlignMethod.CENTER_Y,
        });
    }
}
