/** утилиты рассчитанные уже на конкретный проект **/
import {PosObject} from '../auto_generated/types';
import {makeAlign} from '@kvisaz/phaser-sugar';

export function centerX(anchor: PosObject, target: PosObject) {
    makeAlign(align => align.anchor(anchor).centerX(target))
}

export function center(anchor: PosObject, target: PosObject) {
    makeAlign(align => align.anchor(anchor).center(target))
}


export function addGeneratedButtonSounds(scene: Phaser.Scene) {
    scene.events.on("onButtonClick", () => {
        scene.sound.play("click");
    });

    scene.events.on("onButtonHover", () => {
        scene.sound.play("cardFlip");
    });
}
