import {Align, AlignMethod, layoutChain, makeAlign} from '@kvisaz/phaser-sugar';
import {ViewElementBuilder} from "../../../../assets";
import type {IClassicCardDto, ISpiderConfig, ISpiderStackMap,} from "../../../../common";
import {
    createDefaultSpiderStacksCreator,
    defaultSpiderConfig,
    fitToSize,
    SceneEvents,
    SpiderStackType,
    SpiderView,
} from "../../../../common";
import {GamePlayCard} from "../../../shared";
import {ISpiderWrapEvents} from "./events";
import {SpiderStackCountInfo} from "./SpiderStackCountInfo";
import {GameServiceProvider} from "../../../../services";
import {spiderSourceDeckLayoutStrategy} from "./spiderSourceDeckLayoutStrategy";
import {BaseInfoText} from "../BaseInfoText";
import {cardLayoutConfig} from "../../config.layout";
import {gameConfig} from "../../../../config";

interface IProps {
    scene: Phaser.Scene;
}

const STOCK_CARDS_AFTER_INITIAL_DEAL = 50;

export class SpiderWrap {
    private readonly builder: ViewElementBuilder;
    private spiderView: SpiderView | undefined;
    private stackCountInfo: SpiderStackCountInfo | undefined;
    private readonly sceneEvents: SceneEvents<ISpiderWrapEvents>;
    private readonly unSubs: Array<() => void> = [];

    constructor(private readonly props: IProps) {
        const {scene} = this.props;
        this.builder = new ViewElementBuilder(scene);
        this.sceneEvents = new SceneEvents<ISpiderWrapEvents>({scene});
        this.unSubs.push(() => {
            this.sceneEvents.unSubscribeAll();
        });
        this.subscribeToSceneEvents();
    }

    destroy() {
        this.spiderView?.destroy();
        this.stackCountInfo?.destroy();
        this.unSubs.forEach((unSub) => unSub());
    }

    private subscribeToSceneEvents() {
        const {scene} = this.props;
        const {sceneEvents} = this;

        this.unSubs.push(
            sceneEvents.on("spiderStart", (data) => this.start(data.cards, data.config)),
            sceneEvents.on("spiderStateUpdate", (state) => {
                /**
                 * Глобально блокируем input на сцене во время animation-step.
                 * Это не дает пользователю запускать параллельные команды, пока текущий ход еще не завершен.
                 **/
                scene.input.enabled = state.step === "idle";
                this.stackCountInfo?.update(state);
            }),
        );
    }

    private start(playCards: IClassicCardDto[], config: ISpiderConfig) {
        this.spiderView?.destroy();
        this.stackCountInfo?.destroy();

        const {scene} = this.props;
        const builder = this.builder;
        const playerData = GameServiceProvider.get().playerData.get();
        const cardSize = cardLayoutConfig.cardSize;

        const cardViews = playCards.map(({value, suit}) => {
                const card = new GamePlayCard({
                    scene,
                    suit,
                    value,
                    initStackId: SpiderStackType.STOCK,
                    initSide: "back",
                    theme: playerData.cardsTheme,
                    backAssetName: playerData.cardBackAssetName,
                });

                fitToSize({
                    gameObject: card,
                    width: cardSize.width,
                    height: cardSize.height,
                });

                return card;
            },
        );

        /**
         * сколько до края экрана дозволено карте
         * < 0 - карта заходит за край экрана
         * **/
        const SPIDER_TABLEAU_BOTTOM_SAFE_INSET = -35;
        let stockDealCardCount = 0;

        const stackMap = createDefaultSpiderStacksCreator({
            createCardPlace: () => builder.cardPlace(cardLayoutConfig.cardSize),
            stockLayoutStrategy: (items, inputZone) => spiderSourceDeckLayoutStrategy({
                items,
                inputZone,
                stockDealCardCount,
                stockCardsAfterInitialDeal: STOCK_CARDS_AFTER_INITIAL_DEAL,
            }),
            tableauLayout: 'klondike',
            /**
             * Для длинных tableau включаем адаптивную стратегию с ограничением по нижней границе экрана.
             * Так последняя карта остается видимой даже на сверхдлинных колонках.
             */
            tableauBottomBoundaryY: scene.scale.height - SPIDER_TABLEAU_BOTTOM_SAFE_INSET,
        })();
        stockDealCardCount = stackMap.tableaus.length;

        this.layoutStacks(stackMap);

        const spiderView = new SpiderView({
            scene,
            cardViews,
            stackMap,
            config: config ?? defaultSpiderConfig,
        });
        if (gameConfig.gameDebugNumbersEnabled) {
            this.stackCountInfo = new SpiderStackCountInfo({
                scene,
                builder,
                stackMap,
            });
        }

        const state = spiderView.getState();
        this.stackCountInfo?.update(state);
        /**
         * Синхронизируем input сразу при старте новой игры.
         * Иначе между созданием SpiderView и первым spiderStateUpdate может быть короткое окно с неверным режимом ввода.
         **/
        scene.input.enabled = state.step === "idle";
        spiderView.syncExposedState(); // отдаем состояние до анимированной раздачи
        spiderView.startInitialDeal();
        this.spiderView = spiderView;
    }

    /**
     * Расставляет места стеков на сцене по `cardLayoutConfig`.
     *
     * Здесь двигаются только `cardPlace`:
     * - tableau places становятся в ряд от `cardColumns.left/top`;
     * - foundation places накладываются в одну правую верхнюю точку;
     * - stock place получает позицию из `sourceDeck`.
     *
     * Карты внутри стеков раскладывает не этот метод, а layout strategies в `SpiderStack`.
     */
    private layoutStacks(stackMap: ISpiderStackMap): void {
        const {scene} = this.props;
        const layout = cardLayoutConfig;
        stackMap.tableaus.forEach((stack, index) => {
            Align.setLeftTop(
                stack.cardPlace,
                layout.cardColumns.left + index * (layout.cardSize.width + layout.cardColumns.gap),
                layout.cardColumns.top,
            );
        });

        const basePlaces = stackMap.foundations.map(e => e.cardPlace);
        const baseRow = layoutChain({
            children: basePlaces,
            alignToAnchor: AlignMethod.CENTER_Y,
            alignToNext: AlignMethod.RIGHT_TO,
            nextOffsetX: layout.collectedCards.gap
        })
        makeAlign((align) => {
            align
                .anchorSceneScreen(scene)
                .leftIn(baseRow, layout.collectedCards.left)
                .topIn(baseRow, layout.collectedCards.top);
        });


        makeAlign((align) => {
            align
                .anchorSceneScreen(scene)
                .leftIn(stackMap.stock.cardPlace, layout.sourceDeck.left)
                .topIn(stackMap.stock.cardPlace, layout.sourceDeck.top);
        });
    }

    /** Создает счетчик собранных баз у видимого места foundation. */
    private createBaseInfoText(stackMap: ISpiderStackMap): BaseInfoText | undefined {
        const visibleFoundation = stackMap.foundations[0];
        if (!visibleFoundation) {
            return undefined;
        }

        return new BaseInfoText({
            scene: this.props.scene,
            anchor: visibleFoundation.cardPlace,
        });
    }
}
