import {BgAssetManager, ConsumablesFlow, SoundPlayerFeature} from "../shared";
import {SpiderGameScenes} from "../scenes";
import {SpiderStartView} from "./SpiderStartView";
import {BonusShopDialogManager, SpiderSelectStyleDialogManager, SpiderSettingsDialogManager} from '../dialog';
import {addButtonInteractivity, testButtonViewInteractivity} from '../auto_generated/utils/addButtonViewInteractivity';
import {gameConfig} from '../../config';
import {attachSoundForEvents, musicConfig} from '../../config.sound';
import {getCurrentLocale} from '../../assets';
import {ParticleEffectLayer, SceneLifeCycle, setSceneLocale} from '../../common';

export class SpiderStartScene extends Phaser.Scene {
    constructor() {
        super(SpiderGameScenes.SpiderStart);
    }

    preload() {
    }

    create() {
        const scene = this;
        new SceneLifeCycle({scene});
        setSceneLocale(scene, getCurrentLocale());

        addButtonInteractivity(scene);
        testButtonViewInteractivity(scene);

        new BgAssetManager({scene});
        attachSoundForEvents(scene);
        new SoundPlayerFeature({scene, musicConfig});
        new SpiderSettingsDialogManager({scene, gameConfig});
        new SpiderSelectStyleDialogManager({scene});
        new BonusShopDialogManager({scene});
        new ConsumablesFlow(scene);
        new SpiderStartView({scene});
        new ParticleEffectLayer({scene});
    }
}
