function createCardThemeSelectState(props: {
  scene: Phaser.Scene;
  isSelected: boolean;
  width: number;
  height: number;
}): Phaser.GameObjects.Image | ShopSelectLabel {
  const {scene, isSelected, width, height} = props;

  if (isSelected) {
    const checkmark = createAssetChild(scene, {
      asset: assetsViewsAutoAssets.iconCheckmark100,
      x: 150,
      y: 245,
      width: 100,
      height: 100,
    });
    setLeftTop(checkmark, 150 - width / 2, 245 - height / 2);
    return checkmark as Phaser.GameObjects.Image;
  }

  const chooseButton = new ShopSelectLabel({scene});
  setLeftTop(chooseButton, 145 - width / 2, 286 - height / 2);
  return chooseButton;
}
