import {hasInSet} from "../../common";
import {IInAppPurchase, InAppApiService, InAppShopItemDto} from "./types";

interface IMockShopServiceProps {
    availablePurchaseIds: string[];
}

/** Создает моковые данные **/
export class MockInAppService implements InAppApiService {
    private readonly availablePurchases: Set<InAppShopItemDto>;

    constructor(private readonly props: IMockShopServiceProps) {
        this.availablePurchases = new Set<InAppShopItemDto>(
            props.availablePurchaseIds.map((id, index) => {
                const price = Math.floor((index+1) * 39) + 10;
                const currency = "yan";
                return {
                    id,
                    price,
                    currency,
                    priceString: `${price} ${currency}`,
                    priceCurrencyCode: currency,
                };
            })
        );
    }

    async preload(): Promise<void> {
    }

    getShopData(): Set<InAppShopItemDto> | undefined {
        if (this.availablePurchases.size === 0) return;
        return new Set(this.availablePurchases);
    }

    /** Создает mock pending-покупку без начисления и consumePurchase. */
    async purchase(purchaseId: string): Promise<IInAppPurchase> {
        if (!hasInSet(this.availablePurchases, (next) => next.id === purchaseId)) {
            throw new Error("purchase not configured");
        }

        return {
            productID: purchaseId,
            purchaseToken: `mock-${purchaseId}-${Date.now()}`,
        };
    }

    /** В mock-режиме нет внешнего списка pending-покупок. */
    async getPendingPurchases(): Promise<IInAppPurchase[]> {
        return [];
    }

    /** Mock consume не делает внешних действий. */
    async consumePurchase(): Promise<void> {
    }
}
