import {SafeWindowMessagesAdapter} from "../../events/SafeWindowMessagesAdapter";
import {SceneEvents} from "../../events";
import {onSceneShutdown} from "../onSceneShutdown";
import {ISceneLifeCycleWindowMessages} from "./events";

interface ISceneLifeCycleProps {
    scene: Phaser.Scene;
}

interface ISceneLifeCycleSoundEvents {
    soundMuteRequest: { owner: "lifecycle"; muted: boolean };
}

/**
 * Содержит прежнюю lifecycle-логику platform `pause_game/resume_game`, но listeners
 * намеренно не подключаются в constructor.
 *
 * Ошибочный путь был именно в связке listener -> `scene.pause()/scene.resume()`:
 * на мобильных браузерах Yandex SDK, Phaser и сам браузер уже имеют свой lifecycle,
 * а дополнительная ручная пауза сцены может оставить игру в paused-состоянии после
 * возврата во вкладку.
 *
 * Сейчас прекращение ввода и звука гарантируется другими flow:
 * - рекламный overlay блокирует ввод поверх текущей сцены;
 * - `SpiderAdOverlayManager` отправляет `soundMuteRequest` с owner `ad`;
 * - Phaser/browser сами обрабатывают скрытие вкладки на уровне игрового loop.
 */
export class SceneLifeCycle {
    private readonly messages = new SafeWindowMessagesAdapter<ISceneLifeCycleWindowMessages>({
        allowedOrigins: [window.location.origin],
    });

    private readonly sceneEvents: SceneEvents<ISceneLifeCycleSoundEvents>;
    private readonly unSubs: Array<() => void> = [];
    /**
     * Запоминает, что именно этот lifecycle поставил сцену на паузу.
     *
     * Без этого `resume_game` мог бы снять чужую паузу: например, модальное окно,
     * переход между сценами или другой flow остановил сцену по своей причине.
     * Правило простое: возобновляем только то, что остановили сами.
     */
    private isPausedByLifecycle = false;

    /** Создает lifecycle-guard без подключения platform pause/resume listeners. */
    constructor(private readonly props: ISceneLifeCycleProps) {
        this.sceneEvents = new SceneEvents<ISceneLifeCycleSoundEvents>({scene: props.scene});

        /**
         * Не подключаем эти listeners: именно они запускали ошибочную ручную паузу сцены на мобильных устройствах
         *
         * Было:
         * - `this.messages.on("pause_game", () => this.pauseScene())`;
         * - `this.messages.on("resume_game", () => this.resumeScene())`.
         *
         * Код `pauseScene/resumeScene` оставлен ниже как наглядный след причины бага,
         * но не должен вызываться из platform lifecycle.
         */
        this.unSubs.push(
            // this.messages.on("pause_game", () => this.pauseScene()),
            // this.messages.on("resume_game", () => this.resumeScene()),
            onSceneShutdown(props.scene, () => this.destroy()),
        );
    }

    /** Снимает подписки и отменяет временный lifecycle mute у сценового владельца звука. */
    destroy(): void {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        this.messages.unSubscribeAll();
        this.requestSoundControl({muted: false});
    }

    /** Ставит активную сцену на паузу и просит сценовый звук временно замьютиться. */
    private pauseScene(): void {
        const {scene} = this.props;
        const sceneKey = scene.scene.key;

        /**
         * События `pause_game` глобальные для window, а SceneLifeCycle создается на разных сценах.
         * Неактивную сцену не трогаем, чтобы старые/фоновые сцены не записали себе ложное
         * `isPausedByLifecycle` и не начали оживать на следующем `resume_game`.
         */
        if (!scene.scene.isActive(sceneKey)) {
            return;
        }

        this.requestSoundControl({muted: true});
        this.isPausedByLifecycle = true;
        scene.scene.pause(sceneKey);
    }

    /** Возобновляет только сцену, которую ранее остановил этот lifecycle. */
    private resumeScene(): void {
        const {scene} = this.props;
        const sceneKey = scene.scene.key;

        /**
         * Возобновляем только если одновременно:
         * - pause был сделан этим lifecycle;
         * - Phaser все еще считает эту сцену paused.
         *
         * Это защищает от конфликтов с другими владельцами паузы и от повторных resume-событий.
         */
        if (this.isPausedByLifecycle && scene.scene.isPaused(sceneKey)) {
            scene.scene.resume(sceneKey);
        }

        this.isPausedByLifecycle = false;
        this.requestSoundControl({muted: false});
    }

    /** Сообщает звуковой фиче о временном mute рекламы, не меняя sound manager напрямую. */
    private requestSoundControl({muted}: { muted: boolean }): void {
        this.sceneEvents.emit("soundMuteRequest", {
            owner: "lifecycle",
            muted,
        });
    }
}
